options(survey.lonely.psu='adjust');root<-'./TB_metabolome_exposome_20261115_2130';out<-'./系统复审与优化_20261116';.libPaths(c(file.path(root,'analysis_MWAS_ExWAS/Rlib'),.libPaths()));suppressPackageStartupMessages(library(survey));a<-as.data.frame(readRDS(file.path(root,'analysis_MWAS_ExWAS/derived/analysis_2011-2012.rds')));a$birth<-factor(a$foreign_born,levels=c(0,1));a$smoking<-factor(a$smoking);a$y<-ifelse(a$QFT==1&a$TST10==0,1,ifelse(a$QFT==0&a$TST10==1,0,NA));a$blood<-ifelse(a$LBXBCD>0,log2(a$LBXBCD),NA);a$urine<-ifelse(a$URXUCD>0,log2(a$URXUCD),NA);a$ucr<-ifelse(a$urine_creat>0,log2(a$urine_creat),NA);cv<-c('age','sex_male','race','educ','PIR','birth','smoking');a$.dom<-a$age>=20&!is.na(a$y)&complete.cases(a[,c(cv,'blood','urine','ucr')]);a$.dom[is.na(a$.dom)]<-FALSE;ok<-is.finite(a$WTSA2YR)&a$WTSA2YR>0&!is.na(a$SDMVSTRA)&!is.na(a$SDMVPSU);d<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTSA2YR,nest=TRUE,data=a[ok,]);d<-subset(d,.dom);eq<-list(blood_only=y~blood+ucr+age+sex_male+race+educ+PIR+birth+smoking,urine_only=y~urine+ucr+age+sex_male+race+educ+PIR+birth+smoking,joint=y~blood+urine+ucr+age+sex_male+race+educ+PIR+birth+smoking);res<-list();for(nm in names(eq)){fit<-tryCatch(svyglm(eq[[nm]],d,family=quasibinomial()),error=identity);if(inherits(fit,'error')){res[[length(res)+1]]<-data.frame(model=nm,term='error',n=nrow(d$variables),status=conditionMessage(fit));next};for(term in intersect(c('blood','urine'),names(coef(fit)))){b<-coef(fit)[term];se<-sqrt(diag(vcov(fit)))[term];df<-fit$df.residual;res[[length(res)+1]]<-data.frame(model=nm,term=term,n=nrow(d$variables),qft_only=sum(d$variables$y==1),tst_only=sum(d$variables$y==0),design_df=degf(d),residual_df=df,OR=unname(exp(b)),low=unname(if(df>0)exp(b-qt(.975,df)*se) else NA),high=unname(if(df>0)exp(b+qt(.975,df)*se) else NA),p=unname(if(df>0)2*pt(-abs(b/se),df) else NA),status=ifelse(fit$converged,'converged','nonconverged'))}};z<-do.call(rbind,res);write.csv(z,file.path(out,'数据表/17_共同样本血镉尿镉.csv'),row.names=FALSE);print(z)
